-- ==== بذر قدرة phone_verification (مُولَّد آلياً من buildSeedSQL(features.manifest.js)) ====
-- لا يُحرَّر يدوياً — أي تعديل مستقبلي يجب أن يبدأ من src/registry/features.manifest.js
-- ثم إعادة توليد هذا السطر عبر buildSeedSQL، تماماً كنمط sql/capability_seed_m2.sql.
-- UPSERT فقط (on conflict) — لا يمس أي قدرة أخرى موجودة، ولا يُدرج أي ربط بباقة
-- (plan_features) — ذلك قرار Super Admin عبر لوحة الأدمن، لا جزءاً من هذا البذر.
insert into public.feature_flags(key,name,description,type,scope,kind,module,parent_key,category_id,lifecycle_status,runtime_status,sort_order,icon,enabled_global,default_value,allowed_values,metric,unit,upgrade_message,tags,required_permissions,is_public,public_label) values ('phone_verification','تحقق رقم الهاتف (OTP)','تحقق من ملكية رقم هاتف العميل عبر رمز OTP لمرة واحدة عند إتمام الطلب (قيد التطوير — Phase 1: تأسيس الهوية وقاعدة البيانات فقط، بلا فرض فعلي على الطلبات وبلا مزوّد SMS متصل)','feature','restaurant','component','menu','menu_checkout',(select id from public.feature_categories where key = 'customers'),'active','preview',10,'🔐',false,null,null,null,null,null,'{}'::text[],'{}'::text[],false,null) on conflict(key) do update set name=excluded.name,description=excluded.description,type=excluded.type,scope=excluded.scope,kind=excluded.kind,module=excluded.module,parent_key=excluded.parent_key,category_id=excluded.category_id,lifecycle_status=excluded.lifecycle_status,runtime_status=excluded.runtime_status,sort_order=excluded.sort_order,icon=excluded.icon,enabled_global=excluded.enabled_global,default_value=excluded.default_value,allowed_values=excluded.allowed_values,metric=excluded.metric,unit=excluded.unit,upgrade_message=excluded.upgrade_message,tags=excluded.tags,required_permissions=excluded.required_permissions,is_public=excluded.is_public,public_label=excluded.public_label,updated_at=now();
